#!/usr/bin/env python3
"""Build pinned IANA vanguard TZif with upstream zic; no Cargo/build.rs or system TZ.

Usage: python3 generate_tzdb.py /path/to/tzdata2025b.tar.gz /path/to/tzcode2025b.tar.gz
Requires a C compiler, make and awk. Inputs are verified before extraction.
"""

import hashlib
import pathlib
import re
import subprocess
import sys
import tarfile
import tempfile

INPUTS = (
    "11810413345fc7805017e27ea9fa4885fd74cd61b2911711ad038f5d28d71474",
    "05f8fedb3525ee70d49c87d3fae78a8a0dbae4fe87aa565c65cda9948ae135ec",
)


def generate(archives, destination):
    for source, expected in zip(archives, INPUTS, strict=True):
        if hashlib.sha256(source.read_bytes()).hexdigest() != expected:
            raise SystemExit(f"Pinned IANA archive SHA256 mismatch: {source}")
    # Keep the exact PHP 8.5.0 / chrono-tz 0.10.4 identifier set, including aliases.
    names = sorted(
        set(re.findall(r'name: "([^"]+)"',
                       (destination.parents[1] / "src/support/calendar/tail_rules.rs").read_text())),
        key=str.lower,
    )
    if len(names) != 598:
        raise SystemExit("Pinned timezone identifier count mismatch")
    with tempfile.TemporaryDirectory(prefix="openrust-iana2025b-") as temporary:
        upstream = pathlib.Path(temporary) / "upstream"
        upstream.mkdir()
        for archive in archives:
            with tarfile.open(archive) as source:
                source.extractall(upstream, filter="data")
        if (upstream / "version").read_text().strip() != "2025b":
            raise SystemExit("Pinned IANA version mismatch")
        subprocess.run(
            ["make", "zic", "vanguard.zi", "PACKRATDATA=", "PACKRATLIST="],
            cwd=upstream, check=True,
        )
        zones = pathlib.Path(temporary) / "zoneinfo"
        subprocess.run(
            [str(upstream / "zic"), "-b", "slim", "-d", str(zones), "vanguard.zi"],
            cwd=upstream, check=True,
        )
        blob = bytearray()
        ranges = {}
        entries = []
        for name in names:
            data = (zones / name).read_bytes()
            if not data.startswith(b"TZif"):
                raise SystemExit(f"Invalid upstream TZif: {name}")
            if data not in ranges:
                start = len(blob)
                blob.extend(data)
                ranges[data] = (start, len(blob))
            start, end = ranges[data]
            entries.append(f'    ("{name}", {start}..{end}),')
        (destination / "tzif.data").write_bytes(blob)
        output = [
            "//! Generated by generate_tzdb.py from official IANA 2025b vanguard data.",
            "//! Sources, hashes, regeneration and public-domain license: SOURCES.md.",
            "", "pub(super) const ZONES: &[(&str, std::ops::Range<usize>)] = &[",
            *entries, "];", "",
        ]
        (destination / "tzif.rs").write_text("\n".join(output))
        print(f"IANA 2025b vanguard: {len(names)} names, {len(ranges)} unique TZif, {len(blob)} bytes")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit(__doc__)
    generate([pathlib.Path(arg).resolve() for arg in sys.argv[1:]],
             pathlib.Path(__file__).resolve().parent)
